{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "하천변 보행로가 도시공원이 아니라는 이유만으로 서울시 금연구역 지정 대상에서 제외되는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "하천변 보행로는 도시공원이 아니더라도 서울시 금연구역 지정 대상에서 제외되지 않습니다. 조례 제5조제1항제2호는 「하천법」에 따른 하천 연변의 보행자길을 금연구역 지정 대상으로 정하고 있으므로, 도시공원 여부와 무관하게 지정될 수 있습니다. 따라서 공원이 아니라는 이유만으로 지정 대상에서 빠진다고 볼 수 없습니다.",
          "b_ids": "금연:제5조제1항제1호, 금연:제5조제1항제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
